WITH store_cum AS ( SELECT ss.ss_item_sk AS item_sk, ss.ss_sold_date_sk AS date_sk, ss.ss_net_profit AS net_profit, SUM(ss.ss_net_profit) OVER (PARTITION BY ss.ss_item_sk ORDER BY ss.ss_sold_date_sk ROWS UNBOUNDED PRECEDING) AS cum_store_profit FROM store_sales ss ), web_cum AS ( SELECT ws.ws_item_sk AS item_sk, ws.ws_sold_date_sk AS date_sk, ws.ws_net_profit AS net_profit, SUM(ws.ws_net_profit) OVER (PARTITION BY ws.ws_item_sk ORDER BY ws.ws_sold_date_sk ROWS UNBOUNDED PRECEDING) AS cum_web_profit, ws.ws_web_site_sk AS site_sk FROM web_sales ws ) SELECT i.i_item_id, i.i_product_name, COALESCE(sc.date_sk, wc.date_sk) AS date_sk, COALESCE(sc.cum_store_profit,0) AS cum_store_profit, COALESCE(wc.cum_web_profit,0) AS cum_web_profit, COALESCE(wc.cum_web_profit,0) - COALESCE(sc.cum_store_profit,0) AS profit_diff, CASE WHEN COALESCE(wc.cum_web_profit,0) - COALESCE(sc.cum_store_profit,0) > 50000 THEN 'Web Dominant' WHEN COALESCE(wc.cum_web_profit,0) - COALESCE(sc.cum_store_profit,0) < -50000 THEN 'Store Dominant' ELSE 'Balanced' END AS dominance_flag, w.web_name AS web_site_name FROM store_cum sc FULL OUTER JOIN web_cum wc ON sc.item_sk = wc.item_sk AND sc.date_sk = wc.date_sk JOIN item i ON i.i_item_sk = COALESCE(sc.item_sk,wc.item_sk) LEFT JOIN web_site w ON wc.site_sk = w.web_site_sk WHERE i.i_category = 'Electronics' ORDER BY date_sk, profit_diff DESC LIMIT 50
